panels.css:
main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;display:flex;background:#0d0a0c;color:#fff;overflow:hidden}
.seat{flex:0 0 430px;height:1080px;overflow:hidden}.seat{display:flex;align-items:center}.seat img{width:100%;height:auto;object-fit:contain}
.txt{flex:1;padding:70px 46px 0 40px}
.k{font-size:30px;font-weight:700;color:#F5C518}
.t{font-size:74px;font-weight:900;line-height:1.18;margin-top:10px}
.t em{font-style:normal;color:#EC5C90}
.sub{font-size:28px;font-weight:700;color:#e9dfe4;margin-top:14px}
ul{list-style:none;margin-top:36px}
li{font-size:31px;font-weight:700;line-height:1.4;padding:18px 0;border-bottom:2px dashed rgba(255,255,255,.18)}
li:last-child{border-bottom:none}
li b{display:block;font-size:22px;color:#F5C518;margin-bottom:4px}
li em{font-style:normal;color:#EC5C90;font-size:40px}
